import assert from 'node:assert/strict';
import { fetchAllTickets } from './src/client.mjs';

const originalFetch = globalThis.fetch;
try {
  const calls = [];
  const sleeps = [];
  const responses = [
    new Response(JSON.stringify({ message: 'slow down' }), { status: 429, headers: { 'Retry-After': '1.5' } }),
    new Response(JSON.stringify({ items: [{ id: 'a', title: 'A' }, { id: 'b', title: 'B' }], nextCursor: 'next value' }), { status: 200 }),
    new Response(JSON.stringify({ items: [{ id: 'b', title: 'duplicate' }, { id: 'c', title: 'C' }] }), { status: 200 }),
  ];
  globalThis.fetch = async (url) => {
    calls.push(String(url));
    return responses.shift();
  };

  const tickets = await fetchAllTickets({
    baseUrl: 'https://example.test/api',
    sleep: async (milliseconds) => sleeps.push(milliseconds),
  });
  assert.deepEqual(tickets, [
    { id: 'a', title: 'A' },
    { id: 'b', title: 'B' },
    { id: 'c', title: 'C' },
  ]);
  assert.deepEqual(sleeps, [1500]);
  assert.deepEqual(calls, [
    'https://example.test/api/tickets',
    'https://example.test/api/tickets',
    'https://example.test/api/tickets?cursor=next+value',
  ]);

  globalThis.fetch = async () => new Response(JSON.stringify({ message: 'bad cursor' }), { status: 400 });
  await assert.rejects(
    fetchAllTickets({ baseUrl: 'https://example.test', sleep: async () => assert.fail('must not retry') }),
    /HTTP 400: bad cursor/,
  );
} finally {
  globalThis.fetch = originalFetch;
}
EOF
npm test"

